// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(c) && actor != address(0));

        // lock a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // move past the target block so the answer is knowable
        vm.roll(block.number + 5);
        uint256 target = block.number - 4; // = guesses[actor].block
        bytes32 answer = blockhash(target);

        // first settle: caller wins and the guess is consumed
        vm.prank(actor);
        c.settle();

        // fund the contract so a second payout WOULD succeed if it were attempted
        vm.deal(address(c), 2 ether);

        // rule: a consumed guess can never be settled again
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "a settled guess must be consumed: second settle must revert");
    }
}
